<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Shared\Infrastructure\LongTask\Runner;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskKey;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Delete\SnippetAssetDeleteUsecase;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetFilter;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Batch\SnippetAssetTaskDelete;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;

class SnippetAssetDeleteController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly Runner $runner,
        private readonly SnippetAssetDeleteUsecase $deleteUsecase,
    ) {
    }
    #[OA\Delete(
        path: "/api/document/snippet-asset/{uid}",
        tags: ["Snippet asset"],
        description: "Delete the record",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SnippetAssetApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
    ]
    )
    ]
    public function delete(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Delete Snippet asset");
        $span = $this->startSpan("Delete Snippet asset");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $this->deleteUsecase->delete($uid);
            $this->sql->commit();
            return $response->withStatus(204)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            ;
            $span->end();
        }
    }
    public function deleteAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Delete all for query Snippet asset");
        $span = $this->startSpan("Delete all for query Snippet asset");
        try {
            $params = $request->getQueryParams();
            $filter = new SnippetAssetFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                code: $params['code'] ?? null,
                snippet: isset($params['snippet']) ? new SnippetRef($params['snippet']) : null,
                snippets: isset($params['snippets']) ? explode(",", $params['snippets']) : null,
            );
            $res = $this->runner->run(SnippetAssetTaskDelete::class, ['filter' => $filter]);
            $encoded = json_encode($res);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function checkDeleteAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Check delete all for query Snippet asset");
        $span = $this->startSpan("Check delete all for query Snippet asset");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $info = $this->runner->detail(new TaskKey($uid));
            if (!$info) {
                throw new NotFoundException('-');
            }
            $encoded = json_encode($info);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
